import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;
import org.jetbrains.annotations.Nullable;

public class ManaBeanBlock extends Block implements EntityBlock, BlockItemProvider {
	private static final int MAX_AGE = 7;
	public static final IntegerProperty AGE = BlockStateProperties.AGE_7;
	private static final VoxelShape SHAPE = Shapes.box(0.35, 0.875, 0.35, 0.65, 1, 0.65);
	private static final VoxelShape BEAN_POD_0 = Shapes.box(0.4375, 0.6875, 0.4375, 0.5625, 0.875, 0.5625);
	private static final VoxelShape BEAN_POD_1 = Shapes.box(0.40625, 0.625, 0.40625, 0.59375, 0.875, 0.59375);
	private static final VoxelShape BEAN_POD_2 = Shapes.box(0.34375, 0.5, 0.34375, 0.65625, 0.875, 0.65625);
	private static final VoxelShape BEAN_POD_3 = Shapes.box(0.28125, 0.3125, 0.28125, 0.71875, 0.875, 0.71875);

	public ManaBeanBlock() {
		super(Properties.of().sound(SoundType.GRASS).mapColor(MapColor.PLANT).dynamicShape().pushReaction(PushReaction.DESTROY).randomTicks().isRedstoneConductor(Blocks::never));
		registerDefaultState(getStateDefinition().any().setValue(AGE, 0));
	}

	@Override
	protected boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
		BlockPos abovePos = pos.above();
		BlockState aboveState = level.getBlockState(abovePos);

		return aboveState.is(BlockTags.LOGS) && aboveState.isFaceSturdy(level, abovePos, Direction.DOWN);
	}

	@Override
	protected void neighborChanged(BlockState state, Level level, BlockPos pos, Block neighborBlock, BlockPos neighborPos, boolean movedByPiston) {
		if(!state.canSurvive(level, pos))
			level.destroyBlock(pos, true);
	}

	@Override
	protected void randomTick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
		double chance = random.nextDouble();
		int currentAge = state.getValue(AGE);

		if(currentAge < MAX_AGE && chance > 0.85)
			level.setBlockAndUpdate(pos, state.setValue(AGE, Math.min(currentAge + 1, MAX_AGE)));
	}

	@Override
	public ItemStack getCloneItemStack(LevelReader level, BlockPos pos, BlockState state) {
		ItemStack stack = new ItemStack(ArcanusBlocks.MANA_BEAN.get());

		if(level.getBlockEntity(pos) instanceof ManaBeanBlockEntity manaBean)
			stack.set(ArcanusDataComponents.ARCANA.get(), manaBean.getArcana());

		return stack;
	}

	@Override
	protected VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext context) {
		int age = state.getValue(AGE);

		return switch(age) {
			case 4 -> Shapes.or(SHAPE, BEAN_POD_0);
			case 5 -> Shapes.or(SHAPE, BEAN_POD_1);
			case 6 -> Shapes.or(SHAPE, BEAN_POD_2);
			case 7 -> Shapes.or(SHAPE, BEAN_POD_3);
			default -> SHAPE;
		};
	}

	@Override
	protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
		builder.add(AGE);
	}

	@Override
	public @Nullable BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
		return new ManaBeanBlockEntity(pos, state);
	}

	@Override
	public Item createItem() {
		return new ManaBeanItem(this, new Item.Properties().food(new FoodProperties.Builder().nutrition(1).fast().alwaysEdible().build()).component(ArcanusDataComponents.ARCANA.get(), ArcanusArcana.NIL.get()));
	}
}

package dev.cammiescorner.arcanus.common.block.entities;

import dev.cammiescorner.arcanus.api.arcana.Arcana;
import dev.cammiescorner.arcanus.common.data_component.ArcanaStack;
import dev.cammiescorner.arcanus.common.registry.ArcanusBlockEntities;
import dev.cammiescorner.arcanus.common.registry.ArcanusDataComponents;
import dev.cammiescorner.arcanus.common.util.ArcanaContainer;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.nbt.Tag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public class AlembicBlockEntity extends BlockEntity implements ArcanaContainer {
	private ArcanaStack arcanaStack = ArcanaStack.EMPTY;

	public AlembicBlockEntity(BlockPos pos, BlockState blockState) {
		super(ArcanusBlockEntities.ALEMBIC.get(), pos, blockState);
	}

	@Override
	public @Nullable Packet<ClientGamePacketListener> getUpdatePacket() {
		return ClientboundBlockEntityDataPacket.create(this);
	}

	@Override
	public CompoundTag getUpdateTag(HolderLookup.Provider registries) {
		CompoundTag tag = super.getUpdateTag(registries);
		saveAdditional(tag, registries);

		return tag;
	}

	@Override
	protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.saveAdditional(tag, registries);

		tag.put("Arcana", ArcanaStack.CODEC.encodeStart(NbtOps.INSTANCE, arcanaStack).result().orElseThrow());
	}

	@Override
	protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);

		if(tag.contains("Arcana", Tag.TAG_COMPOUND))
			arcanaStack = ArcanaStack.CODEC.parse(NbtOps.INSTANCE, tag.getCompound("Arcana")).result().orElseThrow();
		else
			arcanaStack = ArcanaStack.EMPTY;
	}

	@Override
	protected void applyImplicitComponents(DataComponentInput componentInput) {
		super.applyImplicitComponents(componentInput);

		arcanaStack = componentInput.getOrDefault(ArcanusDataComponents.ARCANA_STACK.get(), ArcanaStack.EMPTY);
	}

	@Override
	protected void collectImplicitComponents(DataComponentMap.Builder components) {
		super.collectImplicitComponents(components);

		components.set(ArcanusDataComponents.ARCANA_STACK.get(), arcanaStack);
	}

	@Override
	public ArcanaStack getArcanaStack(int index) {
		return arcanaStack;
	}

	@Override
	public void setArcanaStack(ArcanaStack arcanaStack, int index) {
		this.arcanaStack = arcanaStack;
		setChanged();
	}

	@Override
	public void addArcanaStack(ArcanaStack arcanaStack) {
		if(this.arcanaStack.isEmpty())
			setArcanaStack(arcanaStack, 0);
	}

	@Override
	public int indexOf(ArcanaStack arcanaStack) {
		return 0;
	}

	@Override
	public int size() {
		return 1;
	}

	@Override
	public double maximumArcana() {
		return 64;
	}

	@Override
	public boolean isEmpty() {
		return arcanaStack.isEmpty();
	}

	@Override
	public boolean isFull() {
		return arcanaStack.amount() >= maximumArcana();
	}

	@Override
	public boolean contains(Arcana arcana) {
		return this.arcanaStack.arcana() == arcana;
	}

	@Override
	public List<Direction> inputDirections() {
		return List.of(Direction.EAST, Direction.WEST, Direction.DOWN);
	}

	@Override
	public List<Direction> outputDirections() {
		return List.of(Direction.UP);
	}
}

package dev.cammiescorner.arcanus.common.block.entities;

import dev.cammiescorner.arcanus.common.registry.ArcanusBlockEntities;
import net.minecraft.Util;
import net.minecraft.core.BlockPos;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import java.util.Locale;
import java.util.UUID;

public class MagicDoorBlockEntity extends BlockEntity {
	private UUID ownerId = Util.NIL_UUID;
	private String password = "please";

	public MagicDoorBlockEntity(BlockPos pos, BlockState state) {
		super(ArcanusBlockEntities.MAGIC_DOOR.get(), pos, state);
	}

	@Override
	protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.saveAdditional(tag, registries);

		tag.putUUID("OwnerId", ownerId);
		tag.putString("Password", password);
	}

	@Override
	protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);
		ownerId = tag.getUUID("OwnerId");
		password = tag.getString("Password");
	}

	public LivingEntity getOwner() {
		if(level instanceof ServerLevel server && server.getEntity(ownerId) instanceof LivingEntity livingEntity)
			return livingEntity;

		return null;
	}

	public void setOwner(LivingEntity owner) {
		ownerId = owner.getUUID();
	}

	public String getPassword() {
		return password;
	}

	public void setPassword(String password) {
		this.password = password.toLowerCase(Locale.ROOT);
	}
}

package dev.cammiescorner.arcanus.common.block.entities;

import dev.cammiescorner.arcanus.api.arcana.Arcana;
