import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import org.jetbrains.annotations.Nullable;

public class ManaBeanBlockEntity extends BlockEntity implements RenderDataBlockEntity {
	private Arcana arcana = ArcanusArcana.NIL.get();

	public ManaBeanBlockEntity(BlockPos pos, BlockState blockState) {
		super(ArcanusBlockEntities.MANA_BEAN.get(), pos, blockState);
	}

	@Override
	public @Nullable Packet<ClientGamePacketListener> getUpdatePacket() {
		return ClientboundBlockEntityDataPacket.create(this);
	}

	@Override
	public CompoundTag getUpdateTag(HolderLookup.Provider registries) {
		CompoundTag tag = super.getUpdateTag(registries);
		saveAdditional(tag, registries);

		return tag;
	}

	@Override
	protected void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.saveAdditional(tag, registries);

		tag.putString("Arcana", ArcanusArcana.REGISTRY.getKey(arcana).toString());
	}

	@Override
	protected void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
		super.loadAdditional(tag, registries);

		if(tag.contains("Arcana", Tag.TAG_STRING))
			arcana = ArcanusArcana.REGISTRY.get(ResourceLocation.parse(tag.getString("Arcana")));
		else
			arcana = ArcanusArcana.NIL.get();

		if(hasLevel())
			markUpdated();
	}

	@Override
	public Object getRenderData() {
		return new ColorRenderData(arcana != null ? arcana.color() : Color.fromARGB(0xffffffff));
	}

	protected void markUpdated() {
		setChanged();
		getLevel().setBlockAndUpdate(getBlockPos(), getBlockState());
	}

	public Arcana getArcana() {
		return arcana;
	}

	public void setArcana(Arcana arcana) {
		this.arcana = arcana;
		markUpdated();
	}
}

package dev.cammiescorner.arcanus.common.item;

import dev.cammiescorner.arcanus.api.arcana.Arcana;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.common.block.entities.ManaBeanBlockEntity;
import dev.cammiescorner.arcanus.common.registry.ArcanusArcana;
import dev.cammiescorner.arcanus.common.registry.ArcanusComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusDataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;

import java.util.List;

public class ManaBeanItem extends BlockItem {
	public ManaBeanItem(Block block, Properties properties) {
		super(block, properties);
	}

	@Override
	public InteractionResult place(BlockPlaceContext context) {
		Player player = context.getPlayer();
		Level level = context.getLevel();

		if(player != null && !level.isClientSide()) {
			ItemStack stack = player.getItemInHand(context.getHand());
			InteractionResult result = super.place(context);

			if(result.consumesAction() && level.getBlockEntity(context.getClickedPos()) instanceof ManaBeanBlockEntity manaBean) {
				manaBean.setArcana(stack.getOrDefault(ArcanusDataComponents.ARCANA.get(), ArcanusArcana.NIL.get()));

				return result;
			}
		}

		return super.place(context);
	}

	@Override
	public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity livingEntity) {
		if(stack.getOrDefault(ArcanusDataComponents.ARCANA.get(), ArcanusArcana.NIL.get()) instanceof PrimalArcana arcana)
			ArcanusComponents.addArcana(livingEntity, arcana, 1, false);

		return super.finishUsingItem(stack, level, livingEntity);
	}

	@Override
	public void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltipComponents, TooltipFlag tooltipFlag) {
		Arcana arcana = stack.getOrDefault(ArcanusDataComponents.ARCANA.get(), ArcanusArcana.NIL.get());

		// TODO make this translated better
		tooltipComponents.add(Component.literal("1 ").append(Component.translatable(arcana.translationKey())).withColor(arcana.color().asIntARGB()));
	}
}

package dev.cammiescorner.arcanus.mixin.common;

import com.llamalad7.mixinextras.injector.ModifyReceiver;
import dev.cammiescorner.arcanus.common.block.MagicDoorBlock;
import dev.cammiescorner.arcanus.common.block.entities.MagicDoorBlockEntity;
import dev.cammiescorner.arcanus.common.registry.ArcanusPointsOfInterest;
import dev.cammiescorner.arcanus.common.util.TranslationKeys;
import net.minecraft.ChatFormatting;
import net.minecraft.core.LayeredRegistryAccess;
import net.minecraft.core.registries.Registries;
import net.minecraft.network.chat.ChatType;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.PlayerChatMessage;
import net.minecraft.server.RegistryLayer;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.server.players.PlayerList;
import net.minecraft.world.entity.ai.village.poi.PoiManager;
import net.minecraft.world.entity.ai.village.poi.PoiRecord;
import net.minecraft.world.level.block.state.BlockState;
import org.jetbrains.annotations.Nullable;
import org.spongepowered.asm.mixin.Final;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;

import java.util.List;
import java.util.function.Predicate;

@Mixin(PlayerList.class)
public class PlayerListMixin {
	@Shadow @Final private LayeredRegistryAccess<RegistryLayer> registries;

	@ModifyReceiver(method = "broadcastChatMessage(Lnet/minecraft/network/chat/PlayerChatMessage;Ljava/util/function/Predicate;Lnet/minecraft/server/level/ServerPlayer;Lnet/minecraft/network/chat/ChatType$Bound;)V", at = @At(
		value = "INVOKE",
		target = "Ljava/util/List;iterator()Ljava/util/Iterator;"
	))
	private List<ServerPlayer> restrictMagicDoorChatMessage(List<ServerPlayer> original, PlayerChatMessage chatMessage, Predicate<ServerPlayer> predicate, @Nullable ServerPlayer player, ChatType.Bound parameters) {
		if(player != null && this.registries.compositeAccess().registryOrThrow(Registries.CHAT_TYPE).getResourceKey(parameters.chatType().value()).map(key -> key.equals(ChatType.CHAT)).orElse(false)) {
			ServerLevel world = player.serverLevel();
			PoiManager poiStorage = world.getChunkSource().getPoiManager();

			var beep = new boolean[1];

			poiStorage.getInRange(poiTypeHolder -> poiTypeHolder.is(ArcanusPointsOfInterest.MAGIC_DOOR), player.blockPosition(), 8, PoiManager.Occupancy.ANY).map(PoiRecord::getPos).forEach(pos -> {
				BlockState state = world.getBlockState(pos);
				if(state.getBlock() instanceof MagicDoorBlock doorBlock && world.getBlockEntity(pos) instanceof MagicDoorBlockEntity door) {
					if(chatMessage.signedContent().equalsIgnoreCase(door.getPassword())) {
						doorBlock.setOpen(null, world, state, pos, true);
						player.displayClientMessage(Component.translatable(TranslationKeys.MAGIC_DOOR_ACCESS_GRANTED).withStyle(ChatFormatting.GRAY, ChatFormatting.ITALIC), true);
						beep[0] = true;
					}
				}
			});

			if(beep[0])
				return List.of();
		}
		return original;
	}
}
